        v->kind = NS_CSS_V_SIZE;
        v->u.size.w = a;
        v->u.size.h = b;
        v->u.size.w_unit = NS_CSS_UNIT_NUMBER;
        v->u.size.h_unit = NS_CSS_UNIT_NUMBER;
